import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"收藏夾","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/settings/favorites.md","filePath":"zh-HK/user-guide/settings/favorites.md","lastUpdated":1785993908000}'),s={name:"zh-HK/user-guide/settings/favorites.md"};function n(i,t,l,d,h,g){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="收藏夾" tabindex="-1">收藏夾 <a class="header-anchor" href="#收藏夾" aria-label="Permalink to &quot;收藏夾&quot;">​</a></h1><p>把常用的資料夾、檔案或網址固定下來，一個按鍵就能到達。</p><h2 id="添加收藏" tabindex="-1">添加收藏 <a class="header-anchor" href="#添加收藏" aria-label="Permalink to &quot;添加收藏&quot;">​</a></h2><ul><li><strong>顯示名稱</strong> —— 可選;如果留空且目標是本地路徑，會自動用路徑的檔案名填充。</li><li><strong>目標路徑</strong> —— 本地路徑，或者 <code>http://</code>/<code>https://</code> 網址。</li><li><strong>瀏覽資料夾</strong> / <strong>瀏覽檔案</strong> 按鈕 —— 打開原生選擇器，不用手動輸路徑。</li><li><strong>添加</strong> 按鈕 —— 輸入路徑後才可用。</li></ul><h2 id="管理列表" tabindex="-1">管理列表 <a class="header-anchor" href="#管理列表" aria-label="Permalink to &quot;管理列表&quot;">​</a></h2><p>列表裏每一條收藏都顯示名稱和目標路徑，每行帶獨立操作:</p><ul><li><strong>向上移動</strong> / <strong>向下移動</strong> —— 調整順序，同時也會影響該收藏項在搜尋結果裏相對其他結果的排名。每一行也可以直接拖動左邊的六點手柄來調整順序——設定裏所有可排序列表(結果類型優先級、快速導航順序、側邊欄篩選順序、結果表格列順序)用的都是同一個拖曳手柄。</li><li><strong>編輯此項</strong> —— 把該項加載回上方輸入框以便修改。</li><li><strong>刪除此項</strong> —— 移除。</li></ul><h2 id="收藏項如何出現在搜尋裏" tabindex="-1">收藏項如何出現在搜尋裏 <a class="header-anchor" href="#收藏項如何出現在搜尋裏" aria-label="Permalink to &quot;收藏項如何出現在搜尋裏&quot;">​</a></h2><p>命中的收藏項會在結果裏帶一個 <strong>★</strong> 標記，緊跟在資料夾/路徑標籤旁邊，並且可以用它的顯示名稱搜尋到——如果名稱裏含中文，同樣支援拼音，和其他任何結果一樣。這是 Lertaro 裏最接近&quot;自訂搜尋別名&quot;的功能，參見<a href="./../search-syntax.html#收藏夾-而非自訂別名">搜尋語法</a>。</p>',9)])])}const _=a(s,[["render",n]]);export{u as __pageData,_ as default};
